python
def resetTalliesProofStrip(readings, k):
    a=readings
    out=[]
    total=0
    for x in a:
        total=0 if x==0 else total+x
        out.append(total)
    return out


java
class Solution {
  public int[] resetTalliesProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int total=0;for(int x:a){total=x==0?0:total+x;out.add(total);}}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
